        assertFalse(d.feasible());
        assertEquals(DisplacementPlanner.BLOCKED_BY_PRIORITY, d.reason());
    }

    @Test
    @DisplayName("已起飞预留即使优先级更低也不可挤出")
    void departedReservationCannotBeDisplaced() {
